module TopModule (
    input  clk,
    input  w,
    input  R,
    input  E,
    input  L,
    output Q
);

    // Internal register to hold the state
    reg Q_reg;

    // Synchronous logic: executed on the positive edge of clk
    always @(posedge clk) begin
        // Priority: Load (L) first, then Enable (E), then Shift (w)
        if (L) begin
            // Load the value from R into Q
            Q_reg <= R;
        end else if (E) begin
            // Enable shift: shift in the input w
