module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic [31:0] in,
    output logic [31:0] out
);

    // Internal register to store the previous value of 'in'
    logic [31:0] in_prev;

    // Always block for positive-edge-triggered sequential logic
    always_ff @(posedge clk) begin
        if (reset) begin
            // Active-high synchronous reset: initialize internal state
            in_prev <= 32'd0;
            out     <= 32'd0;
        end else begin
            // Detect falling edge (1 -> 0 transition) on each bit
            // ~in_prev & in is 1 where the bit transitions from 1 to 0
            // out |= ... accumulates these transitions; out stays 1 once set
            out <= out | (~in_prev & in);

            // Update the previous value for the next clock cycle
            in_prev <= in;
        end
    end

endmodule

