module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot encoded state register
    // State A: 2'b01, State B: 2'b10
    reg [1:0] state;
    reg [1:0] next_state;

    // Next-state logic (Mealy)
    always @(*) begin
        case (state)
            2'b01: // State A
                if (x)
                    next_state = 2'b10; // B
                else
                    next_state = 2'b01; // A
            2'b10: // State B
                if (x)
                    next_state = 2'b10; // B (z=0)
                else
                    next_state = 2'b10; // B (z=1) -- stays in B
            default: next_state = 2'b01; // Should not happen with one-hot
        endcase
    end

    // Output logic (Mealy: z depends on state and input x)
    // In State A: z = 0
    // In State B: z = ~x (since B --x=0 (z=1), B --x=1 (z=0))
    assign z = (state == 2'b01) ? 1'b0 : (~x);

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01; // Reset to State A
        else
            state <= next_state;
    end

endmodule

