    output wire       f
);

    // Synthesizable implementation of the Karnaugh map function
    // f = x[3]' * x[2]' * (x[1] * x[0] + x[1]' * x[0]') 
    //    + x[3] * x[2] * (x[1] + x[1]' * x[0])
    //    + x[3] * x[2]' * x[1]

