module TopModule (
    input  clk,
    input  reset,
    input  j,
    input  k,
    output out
);

    // State encoding: 0 for OFF, 1 for ON
    reg [1:0] state, next_state;

    // State register (synchronous reset)
    always @(posedge clk) begin
        if (reset)
            state <= 2'b00;  // Reset to OFF
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always @(*) begin
        case (state)
            2'b00: begin // OFF state
                if (j == 1'b1)
