module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg done
);

    // State encoding for the 3-byte message search FSM
    typedef enum logic [1:0] {
        IDLE    = 2'b00,  // Waiting for a byte with in[3] = 1
        BYTE1   = 2'b01,  // Received first byte, expect byte 2
        BYTE2   = 2'b10,  // Received second byte, expect byte 3
        BYTE3   = 2'b11   // Received third byte, assert done next cycle
    } state_t;

    state_t state, next_state;

    // State register (synchronous, active-high reset)
    always_ff @(posedge clk) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        case (state)
            IDLE: begin
                // Stay in IDLE until we see in[3] = 1
                if (in[3])
                    next_state = BYTE1;
                else
                    next_state = IDLE;
            end

            BYTE1: begin
                // After receiving byte 1, move to BYTE2
                next_state = BYTE2;
            end

            BYTE2: begin
                // After receiving byte 2, move to BYTE3
                next_state = BYTE3;
            end

            BYTE3: begin
                // After receiving byte 3, go back to IDLE
                // done will be asserted in the cycle after this state transition
                next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

    // Output logic: assert done one cycle after the third byte is received
    // We detect the transition from BYTE3 to IDLE (i.e., we are in IDLE
    // and the previous cycle was BYTE3). Since we only have state registers,
    // we use a simple flag that gets set when entering BYTE3 and cleared
    // when leaving BYTE3.
    always_ff @(posedge clk) begin
        if (reset) begin
            done <= 1'b0;
        end else begin
            // done is pulsed high for exactly one clock cycle:
            // when we transition FROM BYTE3 TO IDLE.
            if (state == BYTE3 && next_state == IDLE)
                done <= 1'b1;
            else
                done <= 1'b0;
        end
    end

endmodule

