module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    // ------------------------------------------------------------
    // Parameters – minimal state encoding (2 bits)
    // ------------------------------------------------------------
    typedef enum logic [1:0] {
        S_A = 2'b00,   // reset / idle state
        S_B = 2'b01    // monitoring state
    } state_t;

    // ------------------------------------------------------------
    // Signals
    // ------------------------------------------------------------
    state_t        state,       next_state;
    logic [2:0]    cnt;         // counts 3 clock cycles
    logic [1:0]    w_cnt;       // counts how many of the 3 cycles w=1

    // ------------------------------------------------------------
    // Next‑state / output logic (combinational)
    // ------------------------------------------------------------
    always_comb begin
        next_state = state;
        z          = 1'b0;
        cnt        = 3'b0;
        w_cnt      = 2'b0;

        case (state)
            S_A: begin
                // Stay in A while s = 0; move to B when s = 1
                if (s == 1'b1) begin
                    next_state = S_B;
                    cnt        = 3'b001;   // start counting immediately
                end else begin
                    next_state = S_A;
                    cnt        = 3'b000;
                end
            end

            S_B: begin
                // Slide a window of three clock cycles.
                // cnt is the index within the current window (0,1,2).
                // w_cnt accumulates the number of w=1 occurrences.

                // Count this cycle's w value
                if (w == 1'b1) begin
                    w_cnt = w_cnt + 1'b1;
                end

                // If we have not yet examined three cycles, advance counter
                if (cnt < 3'b100) begin
                    cnt = cnt + 3'b001;
                end else begin
                    // Window of three cycles is complete
                    // If exactly two of the three w's were 1, assert z next cycle
                    if (w_cnt == 2'b10) begin
                        z = 1'b1;
                    end else begin
                        z = 1'b0;
                    end
                    // Reset for the next window
                    cnt        = 3'b001;   // start new window on next clock
                    w_cnt      = 2'b00;
                end

                // If we are exactly at the end of the third cycle (cnt == 3'b100)
                // the window is already processed above; just keep state.
                if (cnt == 3'b100) begin
                    // state stays S_B, next cycle will start a new window
                end
            end
        endcase
    end

    // ------------------------------------------------------------
    // Sequential logic (positive edge triggered, synchronous reset)
    // ------------------------------------------------------------
    always_ff @(posedge clk) begin
        if (reset == 1'b1) begin
            state <= S_A;
        end else begin
            state <= next_state;
        end
    end

