module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // State encoding: 2 bits
    // 2'b00: IDLE (waiting for reset release)
    // 2'b01: ACCEPTING (collecting bits, LSB first)
    // 2'b10: STOP (reset asserted, hold output)
    // 2'b11: DONE (final output stabilization, optional)

    reg [1:0] state;
    reg [31:0] num;   // accumulator for input number (arbitrary length handled by width)
    reg [32:0] comp;  // 2's complement result (extra bit for carry)
    reg [31:0] inv;   // bitwise inverted number
    reg [5:0]  bit_cnt; // bit counter (0 to 31, can be extended)

    // State transition logic (positive edge triggered, asynchronous active-high reset)
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state   <= 2'b00;  // IDLE
            num     <= 32'd0;
            bit_cnt <= 6'd0;
            comp    <= 33'd0;
        end else begin
            case (state)
                2'b00: begin // IDLE
                    // Wait for reset release
                    if (!areset) begin
                        state <= 2'b01; // Transition to ACCEPTING
                        num   <= 32'd0;
                        bit_cnt <= 6'd0;
                    end
                end

                2'b01: begin // ACCEPTING
                    // Collect bits LSB first
                    if (bit_cnt < 6'd32) begin // 32-bit limit for simulation; adjust as needed
                        num   <= {num[30:0], x}; // Shift in new LSB
                        bit_cnt <= bit_cnt + 1'b1;
                        // Optional: stay in ACCEPTING until reset or end of bits
                        // For arbitrary length, we could transition on a valid signal, 
                        // but per spec: "stops when Reset is asserted".
                        // Here we assume continuous input until reset.
                    end else begin
                        // Max bits reached, could transition to DONE or stay accepting
                        // For this implementation, we keep accumulating or stop.
                        // Let's transition to a stabilization state or just hold.
                        // To strictly follow "arbitrary length" and "stops when reset asserted", 
                        // we assume input stream continues until reset.
                        // We will transition to a state where we compute output upon 
                        // reset assertion or a stop condition. 
                        // Here we simply keep state ACCEPTING and wait for reset.
                    end
                end

                2'b10: begin // STOP (Reset asserted)
                    // Hold state and output
                    // comp calculation happens based on current num
                    // We compute 2's complement here to hold the value
                    if (num == 32'd0) begin
                        comp <= 33'd0;
                    end else begin
                        inv   <= ~num;
                        comp  <= {inv[31], {31'd0} + 1'b1}; // 2's complement
                    end
                    state <= 2'b10;
                end

                default: state <= 2'b00;
            endcase
        end
    end

    // Output logic (Moore machine: output depends only on state)
    // z is the most significant bit of the complement, or the whole value?
    // Specification: "output (Z) is the 2's complement of the input"
    // Typically for a serial output, we might output MSB first or hold the result.
    // Given it's a Moore machine and "stops when Reset is asserted", 
    // z likely represents the final complemented value or a serial output.
