    next_state  = state;
    bit_counter = 4'h8;    // default (will be overwritten in FSM)
    data_reg    = 8'h00;
    stop_sample = in;      // default: treat current in as stop sample

    case (state)
        IDLE: begin
            if (~in) begin          // start bit detected (falling edge)
                next_state = START;
                bit_counter = 4'd0;
            end else begin
                next_state = IDLE;
            end
        end

        START: begin
            // Wait one clock cycle to verify the start bit is still 0
            if (in) begin
                // Start bit was not 0 – likely noise; go back to IDLE
                next_state = IDLE;
            end else begin
                next_state = DATA;
            end
        end

        DATA: begin
            // Shift in the data bit (LSB first)
            data_reg = {in, data_reg[7:1]};
            bit_counter = bit_counter + 1'b1;

            if (bit_counter == 4'd8) begin
                // All 8 data bits received; sample the stop bit next cycle
                next_state = STOP;
            end else begin
                next_state = DATA;
            end
        end

        STOP: begin
            stop_sample = in;
            if (in) begin
                // Stop bit correct -> byte received successfully
                next_state = IDLE;
            end else begin
                // Stop bit missing – wait here until it appears
                next_state = STOP;
            end
        end

        ERROR: begin
            // Should not be reached with the given spec, but included for robustness
            next_state = IDLE;
        end
    endcase
end

// ---------- Sequential logic (positive edge triggered) ----------
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        state      <= IDLE;
        bit_counter<= 4'h0;
        data_reg   <= 8'h00;
    end else begin
        state      <= next_state;
        bit_counter<= (state == DATA) ? bit_counter : 4'h0;
        data_reg   <= (state == DATA) ? data_reg : 8'h00;
    end
end

