                // Verify stop bit is high (1).
                if (in == 1'b1) begin
                    // Stop bit correct: assert done and return to IDLE.
                    next_state = IDLE;
                end begin
                    // Stop bit incorrect: stay in STOP and wait for a new start bit.
                    // The FSM will remain here until in goes low (start bit).
                    next_state = STOP;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    // Sequential update for bit_index and shift_reg.
    // We use a separate always block triggered on posedge clk (with reset)
    // to keep the state machine clean. The combinational always block above
    // only determines next_state and the mux-style assignments for out_byte.
    // Here we capture the bit_index advancement and shift_reg update.
    always @(posedge clk) begin
        if (reset) begin
            bit_index <= 4'b0;
        end else begin
            case (state)
                DATA: begin
                    if (bit_index == 4'd7) begin
                        // After the 8th bit, reset index for next byte.
                        bit_index <= 4'b0;
                    end else begin
                        bit_index <= bit_index + 4'd1;
                    end
                end
                // In IDLE, START, STOP we do not advance bit_index;
                // shift_reg is only updated during DATA state.
                default: bit_index <= 4'b0;
            endcase
        end
    end

    // shift_reg update: capture the bit during DATA state.
    // We model it as a simple shift-left with new LSB from 'in'.
    always @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else if (state == DATA) begin
            // Shift left and insert the newly sampled bit as LSB.
            // This runs every clock while in DATA, effectively moving the
            // bit stream into the register.
            shift_reg <= {shift_reg[6:0], in};
        end
        // In other states shift_reg retains its previous value
        // (or could be explicitly held, but holding is default since
        // we only update when state==DATA).
    end

endmodule

