module TopModule (
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

    // 7-bit global branch history register (GHR)
    reg [6:0] ghr;

    // 128-entry Pattern History Table (PHT) of two-bit saturating counters
    // Each counter has 2 bits: [1:0]
    // State encoding: 00 -> Strongly Not Taken, 01 -> Weakly Not Taken,
    //                 10 -> Weakly Taken, 11 -> Strongly Taken
    reg [1:0] pht [0:127];

    // Internal wires for prediction logic
    wire [6:0] index;
    wire [1:0] pht_entry;
    wire taken_internal;

    // Assign the 7-bit index by XORing the PC with the GHR
    assign index = predict_pc ^ ghr;

    // Read the PHT entry at the computed index
    assign pht_entry = pht[index];

    // Determine prediction based on the PHT entry state
    // If the MSB (second bit) is 1, predict Taken; otherwise predict Not Taken
    assign taken_internal = pht_entry[1];

    // Prediction output: taken is high if the predicted direction is Taken
    assign predict_taken = taken_internal;

    // Prediction history output: the GHR value used for this prediction
    assign predict_history = ghr;

    // Training logic
    // When train_valid is asserted, update the PHT and potentially the GHR
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            // Asynchronous reset: zero out GHR and PHT
            ghr <= 7'b0;
            pht <= '0;
        end else begin
            // Default: GHR updates with predicted branch outcome at next cycle
            // (Handled by prediction side below)

            // Training operation
            if (train_valid) begin
                // Compute training index using train_pc XOR train_history
                // Note: In a real implementation, this would use the current GHR,
                // but per specification we use provided train_history for index.
                // Here we use train_pc XOR train_history to index the PHT.
                wire [6:0] train_index = train_pc ^ train_history;

                // Update PHT entry
                if (train_taken) begin
                    // Increment counter (saturating towards Taken/11)
                    if (pht[train_index] < 3)
                        pht[train_index] <= pht[train_index] + 1;
                end else begin
                    // Decrement counter (saturating towards Not Taken/00)
                    if (pht[train_index] > 0)
                        pht[train_index] <= pht[train_index] - 1;
                end

                // If the branch was mispredicted, recover GHR to state after
                // the mispredicting branch completes execution.
                // Per spec: "if the branch being trained is mispredicted, also
                // recover the branch history register to the state immediately
                // after the mispredicting branch completes execution."
                if (train_mispredicted) begin
                    // Recovery logic: The GHR should be updated to reflect
                    // the state after the mispredicting branch.
                    // Since we don't have the exact architectural state,
                    // we update the GHR by XORing out the old history and
                    // XORing in the new history as per gshare mechanics.
                    // However, the spec implies setting it to a known state
                    // or the state post-execution. For this implementation,
                    // we update the GHR based on the train_taken value
                    // and the provided train_history.
                    // A common recovery mechanism is to shift the GHR based
                    // on the actual outcome.
                    if (train_taken)
                        ghr <= {ghr[5:0], 1'b1}; // Shift in Taken
                    else
                        ghr <= {ghr[5:0], 1'b0}; // Shift in Not Taken
                end
            end else begin
                // Prediction side: Update GHR at the next positive clock edge
                // when a prediction is requested.
                // "The branch history register is then updated (at the next
                //  positive clock edge) for the predicted branch."
                if (predict_valid) begin
                    // Update GHR by shifting in the predicted taken outcome
                    if (taken_internal)
                        ghr <= {ghr[5:0], 1'b1};
                    else
                        ghr <= {ghr[5:0], 1'b0};
                end
            end
        end
    end

endmodule

