module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    // Internal register holding the current grid state
    logic [255:0] state;

    // ---------- Next-state logic ----------
    // We compute the next state for every cell in parallel.
    // The grid is 16 rows x 16 columns.
    // Row-major ordering: q[15:0] = row 0, q[31:16] = row 1, …, q[255:240] = row 15.

    logic [255:0] next_state;

    genvar i, r, c;
    generate
        for (i = 0; i < 256; i = i + 1) begin: cell_gen
            // Row and column from bit index.
            // Bit i => row = i / 16, col = i % 16.
            r = i / 16;
            c = i % 16;

            // --- Toroidal Neighbour Counting ---
            // We compute wrapped row/col indices manually for all 8 neighbours.
            // Wrap-around logic: modulo 16 for rows and columns.
            // Row wrap: (r + 1) % 16 or (r + 15) % 16
            // Col wrap: (c + 1) % 16 or (c + 15) % 16

            // Neighbour positions and their wrapped indices:
            // 1. (r+1, c+1)
            logic [3:0] n1_r = (r == 15) ? 4'd0 : r + 1'd1;
            logic [3:0] n1_c = (c == 15) ? 4'd0 : c + 1'd1;
            // 2. (r+1, c)
            logic [3:0] n2_r = (r == 15) ? 4'd0 : r + 1'd1;
            logic [3:0] n2_c = c;
            // 3. (r+1, c-1)
            logic [3:0] n3_r = (r == 15) ? 4'd0 : r + 1'd1;
            logic [3:0] n3_c = (c == 0) ? 4'd15 : c - 1'd1;
            // 4. (r, c+1)
            logic [3:0] n4_r = r;
            logic [3:0] n4_c = (c == 15) ? 4'd0 : c + 1'd1;
            // 5. (r, c-1)
            logic [3:0] n5_r = r;
            logic [3:0] n5_c = (c == 0) ? 4'd15 : c - 1'd1;
            // 6. (r-1, c+1)
            logic [3:0] n6_r = (r == 0) ? 4'd15 : r - 1'd1;
            logic [3:0] n6_c = (c == 15) ? 4'd0 : c + 1'd1;
            // 7. (r-1, c)
            logic [3:0] n7_r = (r == 0) ? 4'd15 : r - 1'd1;
            logic [3:0] n7_c = c;
            // 8. (r-1, c-1)
            logic [3:0] n8_r = (r == 0) ? 4'd15 : r - 1'd1;
            logic [3:0] n8_c = (c == 0) ? 4'd15 : c - 1'd1;

            // Sum the neighbour values.
            // Bit index for a cell at (wr, wc) is: wr * 16 + wc.
            // We access the state vector directly.
            logic [8:0] cnt;
            cnt = state[n1_r * 16 + n1_c] + 
                  state[n2_r * 16 + n2_c] + 
                  state[n3_r * 16 + n3_c] + 
                  state[n4_r * 16 + n4_c] + 
                  state[n5_r * 16 + n5_c] + 
                  state[n6_r * 16 + n6_c] + 
                  state[n7_r * 16 + n7_c] + 
                  state[n8_r * 16 + n8_c];

            // --- Next State Determination ---
            // Rules:
            // 0-1 neighbour  -> 0
            // 2 neighbours   -> keep cur
            // 3 neighbours   -> 1
            // 4+ neighbours  -> 0
            logic next_val;

            // We use a case statement on the lower bits of the count.
            // The count is 0 to 8, so bits 3:0 are sufficient.
            case (cnt[3:0]) // Using lower 4 bits for case
                4'd0, 4'd1: next_val = 1'b0;       // 0 or 1 neighbour -> 0
                4'd2:     next_val = state[i];    // 2 neighbours -> keep cur
                4'd3:     next_val = 1'b1;        // 3 neighbours -> 1
                default:  next_val = 1'b0;        // 4, 5, 6, 7, 8 neighbours -> 0
            endcase

            // Assign the next state bit
            next_state[i] = next_val;
        end
    endgenerate

    // ---------- Sequential edge ----------
    always_ff @(posedge clk) begin
        if (load)
            state <= data;
        else
            state <= next_state;
    end

    // Output assignment.
    // When load is active, q reflects the loaded data (which becomes the initial state).
    // On subsequent cycles q follows the evolving state.
    assign q = load ? data : state;

endmodule

