module TopModule (
    input  clk,
    input  reset,
    input  w,
    output z
);

    // State encoding: 3 bits for 6 states
    // 3'b000 -> A
    // 3'b001 -> B
    // 3'b010 -> C
    // 3'b011 -> D
    // 3'b100 -> E
    // 3'b101 -> F

    reg [2:0] state, next_state;

    // State register (positive edge triggered)
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= 3'b000; // Reset to A
        else
            state <= next_state;
    end

    // Next state logic (combinational)
    always @* begin
        case (state)
            3'b000: begin // A
                if (w)
                    next_state = 3'b000; // A --1--> A
                else
                    next_state = 3'b001; // A --0--> B
            end
            3'b001: begin // B
                if (w)
                    next_state = 3'b011; // B --1--> D
                else
                    next_state = 3'b010; // B --0--> C
            end
            3'b010: begin // C
                if (w)
                    next_state = 3'b011; // C --1--> D
                else
                    next_state = 3'b100; // C --0--> E
            end
            3'b011: begin // D
                if (w)
                    next_state = 3'b000; // D --1--> A
                else
                    next_state = 3'b101; // D --0--> F
            end
            3'b100: begin // E
                if (w)
                    next_state = 3'b011; // E --1--> D
                else
                    next_state = 3'b100; // E --0--> E
            end
            3'b101: begin // F
                if (w)
                    next_state = 3'b011; // F --1--> D
                else
                    next_state = 3'b010; // F --0--> C
            end
            default: next_state = 3'b000;
        endcase
    end

    // Output logic
    // Since the specification does not explicitly define the output z,
    // z is assigned to be 1 when the machine is in state F (3'b101),
    // and 0 otherwise. This reflects the 'F' transition in the state diagram.
    assign z = (state == 3'b101);

endmodule

