module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding (3 bits, 8 states):
    // 000: walk_left
    // 001: walk_right
    // 010: fall_left (falling, was going left before fall)
    // 011: fall_right (falling, was going right before fall)
    // 100: dig_left (digging, was going left before dig started)
    // 101: dig_right (digging, was going right before dig started)
    // 110: reserved
    // 111: reserved

    reg [2:0] state;
    reg [2:0] next_state;

    // Output logic (Moore machine)
    assign walk_left  = (state == 3'b000);
    assign walk_right = (state == 3'b001);
    assign aaah       = (state == 3'b010) | (state == 3'b011);
    assign digging    = (state == 3'b100) | (state == 3'b101);

    // State register
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 3'b000; // walk_left
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        // Default: stay in current state
        next_state = state;

        case (state)
            3'b000: begin // walk_left
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Ground disappeared - fall
                    // Direction preserved: was walking left, so fall left
                    next_state = 3'b010; // fall_left
                end else if (dig && ground) begin
                    // Can dig: walking on ground, dig=1, no bumps affecting priority
                    // But need to check: if bumped while digging has no effect,
                    // but we're starting to dig, so if bumped in same cycle as dig...
                    // Spec: "being bumped while digging has no effect" - but we're entering dig state
                    // "being told to dig when falling or when there is no ground is ignored"
                    // Here we're walking on ground, so dig is valid
                    // But what if bump_left or bump_right also asserted?
                    // Priority: fall > dig > switch directions
                    // If ground=1 and dig=1, but also bump asserted:
                    // Fall has higher precedence than dig, so if !ground would fall,
                    // but ground=1 here. So dig vs switch directions.
                    // "If more than one of these conditions are satisfied, fall has higher precedence than dig, which has higher precedence than switching directions."
                    // Since ground=1, fall condition (!ground) is false.
                    // So dig vs switch directions. 
                    // Being bumped while digging has no effect, but we're just starting to dig.
                    // I think if bump is asserted while dig=1 and ground=1, 
                    // it should still dig (since fall doesn't apply, and dig > switch)
                    // Actually re-reading: "If more than one of these conditions are satisfied, 
                    // fall has higher precedence than dig, which has higher precedence than switching directions."
                    // The three conditions are: fall (ground=0), dig (dig=1 on ground), switch directions (bumped)
                    // If ground=1 and dig=1 and bump asserted: fall doesn't apply (ground=1),
                    // so dig has higher precedence than switch, so it digs.
                    next_state = 3'b100; // dig_left (was walking left)
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped
                    // If bumped on left, walk right; if bumped on right, walk left;
                    // if bumped on both, still switch directions
                    if (bump_left && bump_right) begin
                        // Bumped both sides - switch direction
                        next_state = 3'b001; // walk_right
                    end else if (bump_left) begin
                        next_state = 3'b001; // walk_right
                    end else if (bump_right) begin
                        next_state = 3'b000; // walk_left
                    end
                end
                // Note: if none of the above, stay walking left
            end

            3'b001: begin // walk_right
                if (!ground) begin
                    next_state = 3'b011; // fall_right
                end else if (dig && ground) begin
                    next_state = 3'b101; // dig_right
                end else if (bump_left || bump_right) begin
                    if (bump_left && bump_right) begin
                        next_state = 3'b000; // walk_left
                    end else if (bump_right) begin
                        next_state = 3'b000; // walk_left
                    end else if (bump_left) begin
                        next_state = 3'b000; // walk_left
                    end
                end
            end

            3'b010: begin // fall_left
                // When ground reappears, resume walking in same direction (left)
                if (ground) begin
                    // Ground reappeared while falling - resume walking left
                    next_state = 3'b000; // walk_left
                    // Note: being bumped while falling has no effect,
                    // and being bumped in same cycle ground reappears also doesn't affect direction
                end
                // If still ground=0, stay falling left
                // (next_state stays fall_left by default)
            end

            3'b011: begin // fall_right
                if (ground) begin
                    next_state = 3'b001; // walk_right
                end
            end

            3'b100: begin // dig_left
                // Continue digging if ground=1 and dig=1
                // If ground=0, fall left (since was going left before dig)
                if (!ground) begin
                    next_state = 3'b010; // fall_left
                end else if (!dig) begin
                    // dig went to 0 while ground=1 - stop digging, start walking in current direction
                    // Current direction was left (before dig started), so walk left
                    next_state = 3'b000; // walk_left
                end
                // If ground=1 and dig=1, stay digging left (next_state stays dig_left by default)
            end

            3'b101: begin // dig_right
                if (!ground) begin
                    next_state = 3'b011; // fall_right
                end else if (!dig) begin
                    next_state = 3'b001; // walk_right
                end
                // If ground=1 and dig=1, stay digging right
            end

            // reserved states: just stay put (or could reset, but we'll keep them)
            default: next_state = state;
        endcase
    end

endmodule

Prob142_lemmings2.code:
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

// State encoding: 2 bits
// 2'b00: WALK_LEFT
// 2'b01: WALK_RIGHT
// 2'b10: FALLING
// 2'b11: RESERVED (unused)
typedef enum logic [1:0] {
    WALK_LEFT   = 2'b00,
    WALK_RIGHT  = 2'b01,
    FALLING     = 2'b10
} state_t;

 // Internal register to remember the walking direction during a fall.
 logic [1:0] dir_mem;

 state_t state, next_state;

// Next-state logic (combinational)
always_comb begin
    next_state = state; // Default: stay in current state

    // Default assignments for outputs are handled below via continuous assignments,
    // but we can set defaults here if needed, though typically we rely on the 
    // continuous assignments to override or set them. 
    // To avoid l-value errors, we simply do not assign walk_left/walk_right/aaah 
    // inside this block's case statements, or use blocking assignments (=) 
    // if we keep them here. The safest path is removing them from here.

    case (state)
        WALK_LEFT: begin
            // walk_left assignment removed from here to fix l-value error.
            if (!ground) begin
                // Fall immediately when ground disappears.
                // Store the current direction (left) in memory before transitioning.
                next_state = FALLING;
                dir_mem  = WALK_LEFT;
            end else if (bump_left | bump_right) begin
                // Bump changes direction while on ground.
                if (bump_left & !bump_right)
                    next_state = WALK_RIGHT;
                else if (bump_right & !bump_left)
                    next_state = WALK_LEFT;
                else
                    // Bumped on both sides: switch direction
                    next_state = WALK_RIGHT;
            end
        end

        WALK_RIGHT: begin
            // walk_right assignment removed from here.
            if (!ground) begin
                // Fall immediately when ground disappears.
                // Store the current direction (right) in memory.
                next_state = FALLING;
                dir_mem  = WALK_RIGHT;
            end else if (bump_left | bump_right) begin
                if (bump_left & !bump_right)
                    next_state = WALK_LEFT;
                else if (bump_right & !bump_left)
                    next_state = WALK_RIGHT;
                else
                    next_state = WALK_LEFT;
            end
        end

        FALLING: begin
            // aaah assignment removed from here.
            if (ground) begin
                // Ground reappears: resume walking in the same direction as before the fall.
                if (dir_mem == WALK_LEFT)
                    next_state = WALK_LEFT;
                else
                    next_state = WALK_RIGHT;
            end else begin
                // Still falling. Bump inputs are ignored.
                // State remains FALLING.
            end
        end
    endcase
end

// Output assignments using continuous assignments.
// This resolves the l-value errors and separates combinational logic from sequential logic.
assign walk_left = (state == WALK_LEFT);
assign walk_right = (state == WALK_RIGHT);
assign aaah = (state == FALLING);

// Flip-flops (sequential logic, positive edge triggered)
always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
        state <= WALK_LEFT;
        dir_mem <= WALK_LEFT; // Initialize memory to walk left
    end else begin
        state <= next_state;
        // dir_mem update logic:
        // If transitioning INTO FALLING, retain the dir_mem set during the 
        // combinational phase based on the state being left.
        // If not falling, update dir_mem to current state for future falls.
        dir_mem <= (next_state == FALLING) ? dir_mem : state; 
    end
end

endmodule
